-- Idempotently seed the 12 TravelMateNE rows into the existing public.destinations table.
-- This script contains DML only: it does not create/alter tables or touch RLS/policies.
-- Requires the existing unique constraint on public.destinations(name).

insert into public.destinations (
  name, state, district, description, image_url, latitude, longitude,
  daily_budget, vibes, seasons, details
)
select
  name, state, district, description, image_url, latitude, longitude,
  daily_budget, vibes, seasons, details
from jsonb_to_recordset(
  $destinations$
    [{"name":"Shillong","state":"Meghalaya","district":"East Khasi Hills","description":"Café culture, pine air and lively hill-town energy.","image_url":"/assets/images/destinations/shillong.webp","latitude":25.5788,"longitude":91.8933,"daily_budget":2200,"vibes":["Culture","Food","Budget"],"seasons":["Autumn","Winter","Spring"],"details":{"description_long":"The capital of Meghalaya pairs a relaxed café scene with living Khasi culture and easy access to waterfalls, caves and forest walks.","image":"/assets/images/destinations/shillong.webp","airport":"Shillong Airport (Umroi) / Guwahati","rail":"Guwahati","gem":false,"permit":"none","network":"Strong in town; patchy outside the city.","atm":"Easy in town; carry cash for day trips.","transport":"Shared sumos to Cherrapunji (₹100–250); ASTC buses and shared cabs in town; Dawki cab roughly ₹2,500–3,500 one way.","dishes":["Jadoh","Dohneiiong","Tungrymbai"],"etiquette":"Ask before photographing people or sacred groves. Remove shoes where requested and follow local guides on community land."}},{"name":"Dawki & Umngot","state":"Meghalaya","district":"West Jaintia Hills","description":"Glass-clear river days at the Bangladesh border.","image_url":"/assets/images/destinations/dawki-umngot.webp","latitude":25.187,"longitude":92.0167,"daily_budget":1800,"vibes":["Offbeat","Adventure","Budget"],"seasons":["Winter","Spring"],"details":{"description_long":"A slow river escape where clear water, limestone cliffs and nearby border villages make the journey part of the experience.","image":"/assets/images/destinations/dawki-umngot.webp","airport":"Guwahati Airport (Gau)","rail":"Guwahati","gem":true,"permit":"none","network":"Intermittent near the river; download maps first.","atm":"Very limited. Withdraw cash in Shillong or Jowai.","transport":"Shared Sumo from Shillong (₹250–400); local boats from ₹500; Shillong–Dawki cab about ₹3,000 one way.","dishes":["Jadoh","Pumaloi","Grilled river fish"],"etiquette":"Keep the river pristine, wear a life jacket on boats, and respect village customs near the border."}},{"name":"Kaziranga","state":"Assam","district":"Golaghat","description":"Grassland safaris in one-horned rhino country.","image_url":"/assets/images/destinations/kaziranga.webp","latitude":26.5775,"longitude":93.1711,"daily_budget":2600,"vibes":["Wildlife","Adventure"],"seasons":["Winter","Spring"],"details":{"description_long":"A UNESCO-listed floodplain landscape known for wild rhinos, elephants and memorable dawn safaris across riverine grassland.","image":"/assets/images/destinations/kaziranga.webp","airport":"Jorhat (Rowriah) / Guwahati","rail":"Furkating / Jorhat Town","gem":false,"permit":"none","network":"Good near lodges; weak inside the park.","atm":"ATMs in Kohora and Bokakhat; carry cash for park fees.","transport":"ASTC buses from Guwahati; shared sumos from Jorhat; safari jeeps from ₹3,500 per vehicle.","dishes":["Masor tenga","Duck curry","Pitha"],"etiquette":"Follow park rules, keep voices low and never feed wildlife. Safari zones and timings are managed by park authorities."}},{"name":"Majuli","state":"Assam","district":"Majuli","description":"River-island monasteries, mask makers and slow days.","image_url":"/assets/images/destinations/majuli.webp","latitude":26.95,"longitude":94.18,"daily_budget":1700,"vibes":["Culture","Offbeat","Budget","Food"],"seasons":["Winter","Autumn"],"details":{"description_long":"The world’s largest river island is a place for satra heritage, hand-made masks, Mising hospitality and unhurried ferry crossings.","image":"/assets/images/destinations/majuli.webp","airport":"Jorhat (Rowriah)","rail":"Jorhat Town","gem":true,"permit":"none","network":"Mostly reliable in Kamalabari; patchy in villages.","atm":"A few ATMs; carry cash as ferry schedules can shift.","transport":"Ferries from Nimati Ghat (₹15–50 passenger); rented bicycle or shared auto (₹300–700/day).","dishes":["Pork with bamboo shoot","Apong rice beer","Ali Aye Ligang pitha"],"etiquette":"Dress modestly at satras, remove shoes indoors and ask before taking photos of performances or prayer spaces."}},{"name":"Tawang","state":"Arunachal Pradesh","district":"Tawang","description":"High-altitude monasteries beneath the eastern Himalaya.","image_url":"/assets/images/destinations/tawang.webp","latitude":27.586,"longitude":91.859,"daily_budget":3200,"vibes":["Culture","Adventure"],"seasons":["Spring","Autumn"],"details":{"description_long":"A dramatic mountain route leads to Tawang’s great monastery, high passes and warm Monpa culture. Build in buffer time for road conditions.","image":"/assets/images/destinations/tawang.webp","airport":"Tezpur / Guwahati","rail":"Rangapara North","gem":false,"permit":"ilp","network":"BSNL and Jio pockets in town; no signal on some passes.","atm":"Limited ATMs in town; carry cash for villages and road stops.","transport":"Shared Sumo from Tezpur (₹1,000–1,500); Guwahati–Tawang shared taxi around ₹2,000–3,000.","dishes":["Thukpa","Momos","Zan"],"etiquette":"Tawang is a sacred Monpa centre. Dress respectfully at monasteries, walk clockwise around chortens and ask before photographing rituals."}},{"name":"Ziro Valley","state":"Arunachal Pradesh","district":"Lower Subansiri","description":"Apatani heritage, rice fields and pine-lined trails.","image_url":"/assets/images/destinations/ziro-valley.webp","latitude":27.544,"longitude":93.819,"daily_budget":2400,"vibes":["Culture","Offbeat","Food"],"seasons":["Spring","Autumn"],"details":{"description_long":"The Apatani plateau is known for its distinct living culture, terraced fields, bamboo craft and pine forest walks.","image":"/assets/images/destinations/ziro-valley.webp","airport":"Lilabari / Itanagar (Donyi Polo)","rail":"Naharlagun","gem":true,"permit":"ilp","network":"Patchy in villages; some stays offer Wi-Fi.","atm":"Limited ATMs in Hapoli; take cash from Itanagar.","transport":"Shared Sumo from Itanagar (₹500–800); local taxis or cycle hire (₹300–700/day).","dishes":["Pika pila","Smoked pork","Apong rice beer"],"etiquette":"Ask permission before entering private farms or photographing people. Respect community forest and fishing rules."}},{"name":"Dzükōu Valley","state":"Nagaland","district":"Kohima","description":"A high valley of seasonal flowers and quiet trails.","image_url":"/assets/images/destinations/dzukou-valley.webp","latitude":25.53,"longitude":94.03,"daily_budget":2100,"vibes":["Adventure","Offbeat"],"seasons":["Summer","Autumn"],"details":{"description_long":"A beautiful high-altitude trek reached from Kohima, with rolling grassland and seasonal blooms. Local entry and guide requirements can change.","image":"/assets/images/destinations/dzukou-valley.webp","airport":"Dimapur","rail":"Dimapur","gem":true,"permit":"ilp","network":"No dependable signal on trail; arrange meeting points.","atm":"No ATMs on trail. Carry cash from Kohima.","transport":"Shared taxi to Viswema (₹200–350); guide/porter negotiable; entry and hut charges paid locally.","dishes":["Smoked pork","Galho","Axone curry"],"etiquette":"Use designated trails, pack out all waste and follow local entry rules. Weather can change quickly at altitude."}},{"name":"Loktak Lake","state":"Manipur","district":"Bishnupur","description":"Floating phumdis and a lake that moves with light.","image_url":"/assets/images/destinations/loktak-lake.webp","latitude":24.55,"longitude":93.78,"daily_budget":1900,"vibes":["Wildlife","Offbeat","Culture"],"seasons":["Winter","Autumn"],"details":{"description_long":"Loktak is South Asia’s largest freshwater lake, with floating phumdi wetlands and the remarkable Keibul Lamjao National Park.","image":"/assets/images/destinations/loktak-lake.webp","airport":"Imphal (Bir Tikendrajit)","rail":"Dimapur (long onward road journey)","gem":true,"permit":"ilp","network":"Good near Moirang; variable at lake viewpoints.","atm":"ATMs in Moirang and Imphal; limited on the lake.","transport":"Shared taxi Imphal–Moirang (₹100–200); local boat rides from ₹500–1,500.","dishes":["Eromba","Nga-thongba","Singju"],"etiquette":"Choose community-approved boat operators and avoid stepping on or littering floating wetlands."}},{"name":"Reiek","state":"Mizoram","district":"Mamit","description":"A forested peak with Mizo village life nearby.","image_url":"/assets/images/destinations/reiek.webp","latitude":23.684,"longitude":92.613,"daily_budget":1600,"vibes":["Offbeat","Adventure","Budget"],"seasons":["Winter","Spring"],"details":{"description_long":"A peaceful forested ridge and heritage village that make an easy, rewarding day out from Aizawl.","image":"/assets/images/destinations/reiek.webp","airport":"Lengpui (Aizawl)","rail":"Silchar (onward road journey)","gem":true,"permit":"ilp","network":"Good near Aizawl; limited on the hill.","atm":"Withdraw in Aizawl before heading out.","transport":"Shared sumo from Aizawl to Reiek (₹150–250); taxi roughly ₹1,500–2,000 return.","dishes":["Bai","Sawhchiar","Misa mach poora"],"etiquette":"Mizoram observes a strong community ethic. Ask before photographing people and be mindful of local Sunday quiet and church services."}},{"name":"Unakoti","state":"Tripura","district":"Unakoti","description":"Ancient rock carvings hidden in a green hillside.","image_url":"/assets/images/destinations/unakoti.webp","latitude":24.327,"longitude":92.0665,"daily_budget":1500,"vibes":["Culture","Offbeat","Budget"],"seasons":["Winter","Spring"],"details":{"description_long":"A striking archaeological landscape of monumental Shaivite rock reliefs and stone figures tucked into forested hills.","image":"/assets/images/destinations/unakoti.webp","airport":"Agartala (Maharaja Bir Bikram)","rail":"Kumarghat / Dharmanagar","gem":true,"permit":"none","network":"Generally available near Kailashahar; uneven at the site.","atm":"ATMs in Kailashahar; carry small notes for transport.","transport":"Train to Kumarghat then shared auto; Agartala–Unakoti cab roughly ₹3,000–4,000 one way.","dishes":["Mui borok","Chakhwi","Wahan mosdeng"],"etiquette":"Treat the carvings as a living sacred site. Avoid touching sculptures and follow local signage."}},{"name":"Gangtok","state":"Sikkim","district":"Gangtok","description":"Mountain-town energy, monastery bells and momos.","image_url":"/assets/images/destinations/gangtok.webp","latitude":27.3389,"longitude":88.6065,"daily_budget":2400,"vibes":["Food","Culture","Adventure"],"seasons":["Spring","Autumn","Winter"],"details":{"description_long":"Sikkim’s lively capital is a comfortable base for monastery visits, mountain views and day trips into the eastern Himalaya.","image":"/assets/images/destinations/gangtok.webp","airport":"Pakyong / Bagdogra","rail":"New Jalpaiguri (NJP)","gem":false,"permit":"none","network":"Strong in town; variable on mountain routes.","atm":"Good ATM access in Gangtok; carry cash for remote excursions.","transport":"Shared taxi from NJP/Bagdogra (₹400–800 seat); local shared jeeps (₹50–300).","dishes":["Momos","Thukpa","Phagshapa"],"etiquette":"Remove shoes in monasteries and ask before photographing. Carry ID for permits on restricted excursions."}},{"name":"Lachung","state":"Sikkim","district":"Mangan","description":"A mountain village on the way to Yumthang Valley.","image_url":"/assets/images/destinations/lachung.webp","latitude":27.688,"longitude":88.745,"daily_budget":3400,"vibes":["Adventure","Offbeat"],"seasons":["Spring","Autumn"],"details":{"description_long":"A remote mountain settlement and overnight base for Yumthang. Access is regulated and depends on road and weather conditions.","image":"/assets/images/destinations/lachung.webp","airport":"Pakyong / Bagdogra","rail":"New Jalpaiguri (NJP)","gem":true,"permit":"pap","network":"Unreliable beyond Mangan; expect long offline stretches.","atm":"No reliable ATM in Lachung. Carry enough cash from Gangtok.","transport":"Permit-linked shared jeep package from Gangtok (₹3,500–5,000/person, usually 2D/1N).","dishes":["Momos","Thukpa","Gundruk soup"],"etiquette":"Carry original photo ID for permit checks. Follow guide instructions and leave high-altitude meadows untouched."}}]
    $destinations$::jsonb
) as d(
    name text,
    state text,
    district text,
    description text,
    image_url text,
    latitude double precision,
    longitude double precision,
    daily_budget integer,
    vibes text[],
    seasons text[],
    details jsonb
)
on conflict (name) do update set
  state = excluded.state,
  district = excluded.district,
  description = excluded.description,
  image_url = excluded.image_url,
  latitude = excluded.latitude,
  longitude = excluded.longitude,
  daily_budget = excluded.daily_budget,
  vibes = excluded.vibes,
  seasons = excluded.seasons,
  details = excluded.details;
